import React from "react";
import {
  useCurrentFrame,
  useVideoConfig,
  AbsoluteFill,
  interpolate,
  spring,
} from '../remotionShim';
// Fonts
import { makeLoadFont } from '../googleFonts';
const loadInter = makeLoadFont('Inter');
const { fontFamily: interFamily } = loadInter();



export type ChecklistAnimationProps = Record<string, any>;

const AuraBackground: React.FC<{ accentColor: string }> = ({ accentColor }) => {
  const frame = useCurrentFrame();
  const { width, height } = useVideoConfig();

  // Adjusted pulse timings to match the new 3-second slower stagger
  const pulse1 = interpolate(frame, [15, 25, 45], [0, 0.4, 0], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  const pulse2 = interpolate(frame, [35, 45, 65], [0, 0.4, 0], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  const pulse3 = interpolate(frame, [55, 65, 85], [0, 0.4, 0], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  const basePulse = interpolate(Math.sin(frame / 15), [-1, 1], [0.1, 0.2]);
  const dynamicOpacity = basePulse + pulse1 + pulse2 + pulse3;

  return (
    <AbsoluteFill
      style={{
        display: "flex",
        justifyContent: "center",
        alignItems: "center",
        overflow: "hidden",
      }}
    >
      <div
        style={{
          position: "absolute",
          top: height * 0.1,
          left: -width * 0.5,
          width: width * 1.5,
          height: width * 1.5,
          background: `radial-gradient(circle, ${accentColor} 0%, transparent 60%)`,
          opacity: dynamicOpacity,
          filter: "blur(100px)",
          transition: "none",
        }}
      />
      <div
        style={{
          position: "absolute",
          bottom: -height * 0.2,
          right: -width * 0.5,
          width: width * 1.5,
          height: width * 1.5,
          background: `radial-gradient(circle, ${accentColor} 0%, transparent 60%)`,
          opacity: dynamicOpacity * 0.8,
          filter: "blur(100px)",
          transition: "none",
        }}
      />
    </AbsoluteFill>
  );
};

const CheckItem: React.FC<{
  text: string;
  index: number;
  accentColor: string;
}> = ({ text, index, accentColor }) => {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();

  // Slower stagger (20 frames between items)
  const startFrame = 15 + index * 20;
  const delayFrame = Math.max(0, frame - startFrame);

  // Slower Slide & Fade
  const slideProgress = spring({
    fps,
    frame: delayFrame,
    config: { damping: 20, mass: 1.2 },
  });
  const xOffset = interpolate(slideProgress, [0, 1], [-60, 0]);
  const opacity = interpolate(delayFrame, [0, 15], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  // Slower SVG Tick
  const tickDelay = Math.max(0, delayFrame - 8);
  const tickProgress = spring({
    fps,
    frame: tickDelay,
    config: { damping: 18, mass: 1 },
  });
  const strokeDashoffset = interpolate(tickProgress, [0, 1], [24, 0]);

  // Slower Glow Burst
  const burstDelay = Math.max(0, delayFrame - 10);
  const burstScale = interpolate(burstDelay, [0, 20], [0.5, 2.5], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  const burstOpacity = interpolate(burstDelay, [0, 8, 24], [0, 0.8, 0], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  return (
    <div
      style={{
        display: "flex",
        alignItems: "center",
        opacity,
        transform: `translateX(${xOffset}px)`,
        marginBottom: 60,
        position: "relative",
        transition: "none",
      }}
    >
      <div
        style={{
          width: 60,
          height: 60,
          position: "relative",
          marginRight: 40,
          flexShrink: 0,
        }}
      >
        <div
          style={{
            position: "absolute",
            top: 0,
            left: 0,
            right: 0,
            bottom: 0,
            backgroundColor: accentColor,
            borderRadius: "50%",
            transform: `scale(${burstScale})`,
            opacity: burstOpacity,
            filter: "blur(6px)",
            transition: "none",
          }}
        />
        <svg
          viewBox="0 0 24 24"
          style={{
            width: "100%",
            height: "100%",
            position: "relative",
            zIndex: 2,
            filter: `drop-shadow(0 0 8px ${accentColor})`,
          }}
        >
          <path
            d="M20 6L9 17l-5-5"
            fill="none"
            stroke={accentColor}
            strokeWidth="3"
            strokeLinecap="round"
            strokeLinejoin="round"
            strokeDasharray={24}
            strokeDashoffset={strokeDashoffset}
          />
        </svg>
      </div>
      <div
        style={{
          fontSize: 64,
          color: "#FFFFFF",
          fontWeight: 600,
          letterSpacing: "-0.02em",
          textShadow: "0px 4px 12px rgba(0,0,0,0.5)",
        }}
      >
        {text}
      </div>
    </div>
  );
};

const ChecklistAnimation: React.FC<ChecklistAnimationProps> = ({
  backgroundColor = "#050A18",
  transparentBackground = false,
  durationInSeconds = 3,
  title = "Built with intention.",
  items = ["Flexibility", "Structure", "Real Growth"],
  accentColor = "#00C6FF",
}) => {
  const frame = useCurrentFrame();
  const { fps, width } = useVideoConfig();

  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;
  const durationInFrames = Math.round(durationInSeconds * fps);

  // Global Camera Micro-Zoom
  const globalZoom = interpolate(frame, [0, durationInFrames], [1, 1.05], {
    extrapolateRight: "clamp",
  });

  // End Fade (adjusts fade to the very end to allow 3 full seconds)
  const fadeOutStart = durationInFrames - 10;
  const globalOpacity = interpolate(
    frame,
    [fadeOutStart, durationInFrames],
    [1, 0],
    {
      extrapolateLeft: "clamp",
      extrapolateRight: "clamp",
    }
  );

  // Title Animations (speed up exit to make room for slower items)
  const titleProgress = spring({
    fps,
    frame,
    config: { damping: 12, mass: 0.6 },
  });
  const titleScale = interpolate(titleProgress, [0, 1], [0.8, 1]);
  const titleInOpacity = interpolate(frame, [0, 5], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  const titleOutOpacity = interpolate(frame, [10, 15], [1, 0], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  const titleY = interpolate(frame, [10, 15], [0, -40], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  const activeTitleOpacity = frame > 10 ? titleOutOpacity : titleInOpacity;

  // Slower Checklist Track Animation
  const listDelay = Math.max(0, frame - 15);
  const trackProgress = spring({
    fps,
    frame: listDelay,
    config: { damping: 25, mass: 1.5 },
  });
  const trackHeight = interpolate(trackProgress, [0, 1], [0, 100]);
  const trackOpacity = interpolate(listDelay, [0, 10], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  return (
    <AbsoluteFill
      style={{
        backgroundColor: bgColor,
        fontFamily: interFamily,
        transition: "none",
      }}
    >
      <AuraBackground accentColor={accentColor} />

      <div
        style={{
          width: "100%",
          height: "100%",
          display: "flex",
          flexDirection: "column",
          justifyContent: "center",
          alignItems: "center",
          transform: `scale(${globalZoom})`,
          opacity: globalOpacity,
          position: "relative",
          zIndex: 10,
          transition: "none",
        }}
      >
        {/* Title */}
        {activeTitleOpacity > 0 && (
          <div
            style={{
              position: "absolute",
              top: "42%",
              left: 0,
              right: 0,
              textAlign: "center",
              opacity: activeTitleOpacity,
              transform: `translateY(${titleY}px) scale(${titleScale})`,
              fontSize: 84,
              fontWeight: 700,
              color: "#FFFFFF",
              letterSpacing: "-0.03em",
              transition: "none",
            }}
          >
            {title}
          </div>
        )}

        {/* Checklist Block */}
        {frame > 14 && (
          <div
            style={{
              width: "100%",
              maxWidth: width * 0.75,
              position: "relative",
              paddingTop: 40,
            }}
          >
            <div
              style={{
                position: "absolute",
                left: 29, // Centered behind the 60px SVG
                top: 50,
                bottom: 50, // Accounts for margin bottom of items
                width: 2,
                opacity: trackOpacity,
                transition: "none",
              }}
            >
              <div
                style={{
                  width: "100%",
                  height: `${trackHeight}%`,
                  backgroundColor: accentColor,
                  boxShadow: `0 0 12px ${accentColor}, 0 0 24px ${accentColor}`,
                  transition: "none",
                }}
              />
            </div>

            <div style={{ position: "relative", zIndex: 1 }}>
              {items.map((item, i) => (
                <CheckItem
                  key={i}
                  text={item}
                  index={i}
                  accentColor={accentColor}
                />
              ))}
            </div>
          </div>
        )}
      </div>
    </AbsoluteFill>
  );
};

export default ChecklistAnimation;